function appendOutlineMarkerHelp(text) {
  if (!text || text.includes("\u5927\u7EB2\u8BE6\u7565\u6807\u8BB0\u4F7F\u7528\u5E2E\u52A9")) return text;
  const sep = text.endsWith("\n") ? "\n" : "\n\n";
  return text + sep + OUTLINE_MARKER_HELP + "\n";
}
