var WRITING_GUIDE_template_default = "<!--\n# WRITING_GUIDE.md\n\nAI \u5C0F\u8BF4\u5199\u4F5C\u6838\u5FC3\u89C4\u8303\uFF0C\u6BCF\u6B21\u751F\u6210\u65F6\u81EA\u52A8\u8F7D\u5165\u3002\u8BF7\u4E25\u683C\u9075\u5FAA\u3002\n\n---\n-->\n<!-- \u5B57\u6570\u914D\u7F6E:4000-5000 -->\n## \u4E00\u3001\u6838\u5FC3\u521B\u4F5C\u54F2\u5B66\n## \u4E8C\u3001\u57FA\u672C\u98CE\u683C\u4E0E\u53D9\u4E8B\n## \u4E09\u3001\u573A\u666F\u63CF\u5199\n## \u56DB\u3001\u4EBA\u7269\u5851\u9020\n## \u4E94\u3001\u4E8B\u4EF6\u5C55\u5F00 \u2014 \u4ECE\u7B80\u7565\u63D0\u793A\u5230\u5B8C\u6574\u60C5\u8282\n## \u516D\u3001\u5BF9\u8BDD\u5199\u4F5C\n## \u4E03\u3001\u60C5\u8282\u63A8\u8FDB\n## \u516B\u3001\u5F20\u529B\u8BBE\u8BA1\u5DE5\u5177\u7BB1\n### A. \u8D4C\u6CE8\u5347\u7EA7\n### B. \u65F6\u95F4\u538B\u529B\n### C. \u76DF\u53CB\u53D8\u6570\n### D. \u4E24\u96BE\u9009\u62E9\n### E. \u60AC\u5FF5\u53CD\u8F6C\n### F. \u7AE0\u672B\u94A9\u5B50\n### G. \u8282\u594F\u63A7\u5236\n### H. \u53CD\u6D3E\u5851\u9020\n## \u4E5D\u3001\u53BBAI\u5473\u4E13\u9879\u6307\u5357\n### A. \u6838\u5FC3\u539F\u5219\n### B. \u60C5\u611F\u4E0E\u5FC3\u7406\u63CF\u5199\n### C. \u53E5\u5F0F\u4E0E\u6BB5\u843D\u8282\u594F\n### D. \u7ED3\u6784\u5C42\u9762\u53BBAI\u64CD\u4F5C\n### E. \u7279\u6548\u8BCD\u6C47\n<!-- \u5199\u4F5C\u6307\u5357\u5206\u7C7B:\u7981\u7528\u8BCD -->\n## \u5341\u3001\u7F51\u6587\u9AD8\u9891\u7981\u7528\u8BCD\u6E05\u5355\uFF08\u751F\u6210\u6B63\u6587\u65F6\u7981\u6B62\u4F7F\u7528\uFF09\n<!-- /\u5199\u4F5C\u6307\u5357\u5206\u7C7B -->\n## \u5341\u4E00\u3001\u683C\u5F0F\u8981\u6C42\n## \u5341\u4E8C\u3001\u7981\u6B62\u4E8B\u9879\uFF08\u7EDD\u5BF9\u7EA2\u7EBF\uFF09\n## \u5341\u4E09\u3001\u81EA\u68C0\u6E05\u5355\n<!-- \u7F16\u5199\u7C7B\u578B:\u7F51\u6587\u5C0F\u8BF4 -->\n<!-- /\u7F16\u5199\u7C7B\u578B -->\n";

