  { key: "\u7384\u5E7B\u4ED9\u4FA0", name: "\u7384\u5E7B / \u4ED9\u4FA0", keywords: /玄幻|仙侠|修仙|修真|仙魔|洪荒/, defaultText: __default },
  { key: "\u90FD\u5E02\u73B0\u5B9E", name: "\u90FD\u5E02 / \u73B0\u5B9E", keywords: /都市|现实|职场|校园|生活/, defaultText: __default2 },
  { key: "\u79D1\u5E7B", name: "\u79D1\u5E7B", keywords: /科幻|星际|未来|机甲|赛博|太空/, defaultText: __default3 },
  { key: "\u5386\u53F2\u6B66\u4FA0", name: "\u5386\u53F2 / \u6B66\u4FA0", keywords: /历史|武侠|古代|古风|江湖|王朝/, defaultText: __default4 }
